## True when `tag` is present in `tags`, by exact string match -- same rule as
## `WeaponTemplate.has_ability_tag()`.
func has_tag(tag: String) -> bool:
	return tag in tags


## True when `ability_tag` is present in `ability_tags`, by exact string match.
func has_ability_tag(ability_tag: String) -> bool:
	return ability_tag in ability_tags

## The template's health -- the damage counter this fighter is defeated at.
func health() -> int:
	return _template.health


## The template's range in hexes.
func range_hexes() -> int:
	return _template.range_hexes


## The template's attack value.
func attack() -> int:
	return _template.attack


## The template's damage value.
func damage() -> int:
	return _template.damage


